//! Cargo-driven `hnetcfg.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x74050000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff16000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff16000000u64)),
        o => panic!("hnetcfg-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/hnetcfg/hnetcfg_r.o", "dll/win32/hnetcfg/hnetcfg_tlb_t.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:winhttp", "import:ws2_32", "import:shlwapi", "import:advapi32", "import:mpr", "import:xmllite", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "x86_64" => &["dll/win32/hnetcfg/hnetcfg_r.o", "dll/win32/hnetcfg/hnetcfg_tlb_t.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:winhttp", "import:ws2_32", "import:shlwapi", "import:advapi32", "import:mpr", "import:xmllite", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        "aarch64" => &["dll/win32/hnetcfg/hnetcfg_r.o", "dll/win32/hnetcfg/hnetcfg_tlb_t.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:uuid", "engine:oldnames", "import:ole32", "import:oleaut32", "import:winhttp", "import:ws2_32", "import:shlwapi", "import:advapi32", "import:mpr", "import:xmllite", "import:msvcrt", "import:kernel32", "import:kernel32_vista", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("hnetcfg_shims", &["dll/win32/hnetcfg/apps.c", "dll/win32/hnetcfg/hnetcfg.c", "dll/win32/hnetcfg/manager.c", "dll/win32/hnetcfg/policy.c", "dll/win32/hnetcfg/port.c", "dll/win32/hnetcfg/profile.c", "dll/win32/hnetcfg/service.c"])
        .spec2def("dll/win32/hnetcfg/hnetcfg.spec", "hnetcfg.dll")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/winhttp/winhttp.spec", "winhttp.dll", "winhttp")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/mpr/mpr.spec", "mpr.dll", "mpr")
        .import_lib("dll/win32/xmllite/xmllite.spec", "xmllite.dll", "xmllite")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
